// TH14 v1.00b st03.ecl.txt MainSub02:585 GirlD01 wave.
// Source closure: GirlD01 (295-317) + GirlD01_at (319-374).
// Card frame 0 = control phase start; the enemy spawns after OPENING_BUFFER,
// and that spawn is source frame 0 for the attack timeline.
const TIME_LIMIT: int = 1924;      // 120 buffer + 1800 schedule/tail estimate + 4 startup
const OPENING_BUFFER: int = 120;

// Synthetic TH14 mapping: source type 19 -> TH14_BIG_BALL2 (parent),
// source type 5 -> TH14_BALL2 (split child), see touhou-bullets.ecl.
const TH14_BIG_BALL2: int = 656;
const TH14_BALL2: int = 432;

xformdef PARENT_LIFE {
    // Source SHOOT_DATA c=1 deletes the parent at its split (spawn+120).
    set_life(120);
}

// GirlD01_at: the emitter is configured with two RANDRAD samples per volley (r,s)
// shared by both parents and all their children; the children split 120 frames later.
async sub split_children(x1: fx, y1: fx, a1: angle, x2: fx, y2: fx, a2: angle,
                         base: angle, step: angle, layers: int, s0: fx, s1: fx) {
    wait(119); // tasks first run at birth+1, so this resumes at parent birth+120
    emit_split(x1, y1, base, step, layers, s0, s1);
    emit_split(x2, y2, base, step, layers, s0, s1);
}

// EX SHOOT: aim mode 3 (fixed ring), 8 ways, r=random base, s=random per-layer step,
// layer speeds s0..s1. Child ANIM a=1 keeps the 4*velocity spawn retreat.
sub emit_split(x: fx, y: fx, base: angle, step: angle, layers: int, s0: fx, s1: fx) {
    var denom: fx = (layers - 1) as fx;
    for q in 0..layers {
        var speed: fx = s0;
        if layers > 1 { speed = s0 + (s1 - s0) * (q as fx) / denom; }
        var off: int = (step as int) * q;
        var back: fx = 4fx * speed;
        for i in 0..8 {
            var a: angle = ((base as int) + (i * 65536) / 8 + off) as angle;
            _ = fire(TH14_BALL2, 6, x - back * cos(a), y - back * sin(a), speed, a, none, none);
        }
    }
}

// GirlD01_at body: wait 60, then B volleys of 2 parents (aim mode 1 fixed fan,
// base 90deg, spacing A) every 40/20/13/10 frames; A shrinks by 15deg each volley.
async sub girl_attack() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var volleys: int = 2;
    var layers: int = 2;
    var s0: fx = 2fx;
    var gap: int = 40;
    if rank >= RANK_NORMAL { volleys = 4; gap = 20; }
    if rank >= RANK_HARD { volleys = 6; layers = 3; s0 = 2.5fx; gap = 13; }
    if rank >= RANK_LUNATIC { volleys = 8; s0 = 3fx; gap = 10; }
    var spread: int = 16384; // A = pi/2 in BAM
    for v in 0..volleys {
        // etExSet2 samples r then s at configuration time, once per volley.
        var base: angle = rand(65536) as angle;
        var step: angle = rand(65536) as angle;
        var half: int = spread / 2;
        var ap: angle = (16384 + half) as angle; // even fan: +delta/2 first
        var am: angle = (16384 - half) as angle;
        var ex: fx = $self_x;
        var ey: fx = $self_y;
        var back: fx = 0.8fx; // parent ANIM a=1: 4 * 0.2
        _ = fire(TH14_BIG_BALL2, 3, ex - back * cos(ap), ey - back * sin(ap), 0.2fx, ap, PARENT_LIFE, none);
        _ = fire(TH14_BIG_BALL2, 3, ex - back * cos(am), ey - back * sin(am), 0.2fx, am, PARENT_LIFE, none);
        // parent position at split = spawn + 120*0.2 - 0.8 retreat
        var d: fx = 23.2fx;
        spawn split_children(ex + d * cos(ap), ey + d * sin(ap), ap,
                             ex + d * cos(am), ey + d * sin(am), am,
                             base, step, layers, s0, 0.9fx);
        spread = spread - 2731; // 0.261799 rad
        wait(gap);
    }
}

async sub girl_main() {
    set_invuln(65535);
    set_hitbox(12fx);  // setHitbox(24,24): circular branch r=12
    set_hurtbox(16fx); // setHurtbox(32,32): circular branch r=16
    move_vel(0, 90deg, 2.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN); // moveSpeedTime(60,1,0.0)
    spawn girl_attack();
    wait(120);
    move_speed(80, 1fx, EASE_QUAD_IN); // moveSpeedTime(80,1,1.0)
    wait(60);
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -48fx, 1200, 0, 1000, 0, girl_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
